 const saveProfile=async()=>{if(!authenticated){notify("Sign in to save profile changes");return}setProfileSaving(true);setProfileSaveError("");try{const supabase=createClient();const {data:{user},error:userError}=await supabase.auth.getUser();if(userError||!user)throw userError??new Error("Your session expired. Please sign in again.");const upload=async(file:File|null,kind:"avatar"|"cover")=>{if(!file)return undefined;if(!file.type.startsWith("image/"))throw new Error("Choose an image file.");if(file.size>5*1024*1024)throw new Error("Images must be 5 MB or smaller.");const extension=file.name.split(".").pop()?.toLowerCase()||"jpg";const path=`${user.id}/${kind}-${crypto.randomUUID()}.${extension}`;const {error}=await supabase.storage.from("profile-media").upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return supabase.storage.from("profile-media").getPublicUrl(path).data.publicUrl};const [avatarUrl,coverUrl]=await Promise.all([upload(avatarFile,"avatar"),upload(coverFile,"cover")]);const updates={display_name:profileName.trim(),headline:profileHeadline.trim(),bio:profileBio.trim(),...(avatarUrl?{avatar_url:avatarUrl}:{}),...(coverUrl?{cover_url:coverUrl}:{})};const {error}=await supabase.from("profiles").update(updates).eq("auth_user_id",user.id);if(error)throw error;setCurrentAccount({...currentAccount,name:updates.display_name||currentAccount.name,role:updates.headline||"University community member",avatar:avatarUrl||currentAccount.avatar,coverUrl:coverUrl||currentAccount.coverUrl});setAvatarFile(null);setCoverFile(null);setModal("");notify("Profile saved") }catch(cause){setProfileSaveError(cause instanceof Error?cause.message:"Could not save your profile.")}finally{setProfileSaving(false)}};
