 const openComments=async(p:FeedPost)=>{setActivePost(p);setPostComments([]);setCommentBody("");setCommentsError("");setCommentsLoading(true);setModal("Comments · "+p.author.name);if(typeof p.id==="string"){try{setPostComments(await fetchPostComments(p.id))}catch{setCommentsError("Comments could not be loaded.")}finally{setCommentsLoading(false)}}else setCommentsLoading(false)};
 const toggleLike=async(p:FeedPost)=>{if(typeof p.id!=="string"){const next=!liked.includes(p.id);toggleItem(liked,setLiked,p.id);return}if(!currentProfileId){notify("Sign in to like posts");return}const next=!liked.includes(p.id);toggleItem(liked,setLiked,p.id);try{await setPostLike(p.id,currentProfileId,next)}catch{toggleItem(liked,setLiked,p.id);notify("Could not update like")}};
