 const postCard=(p:FeedPost)=><article id={`post-${p.id}`} className="card post" key={p.id}><div className="post-head"><button className="profile-avatar-link" onClick={()=>openProfile(p.author)} aria-label={`View ${p.author.name} profile`}><Avatar person={p.author}/></button><div className="grow"><b><button className="text-link" onClick={()=>openProfile(p.author)}>{p.author.name}</button></b><div className="muted tiny">{p.author.role} · {p.time}</div></div><button className="icon-btn" onClick={()=>{if(p.author.profileId===currentProfileId){setActivePost(p);setModal("Post actions")}else notify("Post options are available to the author")}} aria-label="Post options"><Ellipsis size={19}/></button></div><p className="post-copy">{p.body}</p>{p.image&&<img className="post-image" src={p.image} alt="Post image"/>}<div className="post-meta"><span><span className="heart-dot"><Heart size={11} fill="currentColor"/></span> {p.likes+(liked.includes(p.id)?1:0)} likes</span><button onClick={()=>void openComments(p)}>{p.comments} comments</button><span>{p.tag}</span></div><div className="post-actions"><button className={liked.includes(p.id)?"selected":""} onClick={()=>void toggleLike(p)}><ThumbsUp size={17}/>{liked.includes(p.id)?"Liked":"Like"}</button><button onClick={()=>void openComments(p)}><MessageCircle size={17}/>Comment</button><button onClick={async()=>{try{await navigator.clipboard.writeText(`${window.location.origin}/?post=${encodeURIComponent(String(p.id))}`);notify("Post link copied")}catch{notify("Could not copy the post link")}}}><Share2 size={17}/>Share</button><button onClick={()=>void toggleSave(p)} className="save-action"><Bookmark size={17} fill={saved.includes(p.id)?"currentColor":"none"}/></button></div></article>;
